import{z as l,x as c,o,c as s,q as E,j as t,D as a,d,s as r,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"预分词正则","description":"","frontmatter":{"title":"预分词正则","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pretokenization-regex.md","filePath":"llm/pretokenization-regex.md","lastUpdated":1791413859000}'),B={name:"llm/pretokenization-regex.md"};function A(p,e,m,h,P,_){const n=c("Mermaid");return o(),s("div",null,[e[2]||(e[2]=E('<h1 id="预分词正则" tabindex="-1">预分词正则 <a class="header-anchor" href="#预分词正则" aria-label="Permalink to &quot;预分词正则&quot;">​</a></h1><div class="epigraph"><p>我们先按字符类别把文本切成块，再在块内做字节对合并，以免 BPE 把空格、字母与标点焊成无法解释的跨界符号。</p><footer>—— 据 Radford 等，GPT-2，2019；对照 Kudo &amp; Richardson，SentencePiece，EMNLP 2018 整理</footer></div><p><a href="/llm/data-constrained-scaling">上一课</a>把预训练课序收在数据约束下的扩展：独特数据不够时按有效数据规划，重复只在头几个 epoch 接近新数据。定律再怎么弯，预训练真正吃进去的，仍是一条已经切好的离散序列。本课打开「词表、配比与并行调度」，不重讲定律，也不重讲 <a href="/llm/bpe-merge-rule">BPE 合并规则</a>里那张有序焊对表。缺口是焊对之前那一层：预分词正则决定哪些边界永远不会被合并。后课的字节回退、数字切分、特殊 token，都默认你会本课的「先切块、再合并」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/bpe-merge-rule">BPE</a> 与 <a href="/llm/unigram-segmentation">Unigram</a> 都假定输入已经是一条符号序列。若把整页 HTML 或一整句中英混排直接丢进合并，频率会把 <code>the(</code>、<code>.\\n</code>、甚至跨词的碎片焊成原子，推理时无法再拆。Sennrich 原实现用空格分词，英语干净，中文、代码、无空格脚本会把整句当成一个超长「词」。需要一种不依赖语言词表、却能禁止跨类合并的前置切分。</p><p>正则预分词要回答的不是「词是什么」，而是：字母、数字、空白、标点各成一类，类与类之间的边界在合并表里不可见。GPT-2 把这件事写成一条 Unicode 属性正则；SentencePiece 选择几乎不做预分词，把空格当普通字符。两条路对后续词表的形状完全不同。</p><p><span class="marginnote">直觉类比：BPE 的「合并」就是把语料里反复相邻出现的符号对焊成一个新符号。预分词像先把乐高按颜色分盒，再各自在盒内拼装——不同盒子的零件永远不混，<code>the(</code> 这类「词焊标点」的跨界怪符号就造不出来了。</span></p><h3 id="空格预分词盖不住的脚本" tabindex="-1">空格预分词盖不住的脚本 <a class="header-anchor" href="#空格预分词盖不住的脚本" aria-label="Permalink to &quot;空格预分词盖不住的脚本&quot;">​</a></h3><p>空格切分默认「词」已经在空白处断开。中日文、泰语、代码缩进、Markdown 表格都不满足。若仍强行按空白切，一整段汉字会作为单块进入 BPE，合并名额被超长块吃掉，短词反而焊不出来。<a href="/llm/tokenizer-design">分词器设计</a>已经指出预分词是冻结的承诺；本课只补这条承诺在工程里长什么样。</p><p><span class="marginnote">正则切出的块不是语言学词。<code>&#39;s</code>、<code>&#39;ll</code> 出现在 GPT-2 的模式里，只因为英语缩写频率高，不是因为词法分析器懂助动词。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>GPT-2 一类字节级 BPE 的前置步骤是：用正则把原文打成互不重叠的片段，再把每个片段编成 UTF-8 字节，最后只在片段内部跑合并表。典型模式会匹配：英语缩写、可选空格加字母串、可选空格加数字串、可选空格加非字母数字串、以及尾部空白。字母块与数字块之间没有可合并的相邻对，于是 <code>GPT2</code> 与 <code>2024</code> 不会焊在一起。</p><p><span class="marginnote">数字实例：<code>foo_bar</code> 在「字母块 / 其他块」的正则下切成 <code>foo</code>、<code>_</code>、<code>bar</code> 三块，块间永不相焊。但注意切块只保证「边界不焊」，不保证「块内怎么焊」——<code>2024</code> 若被 <code>\\p{N}+</code> 收进一块，块内 BPE 仍可能把它焊成 <code>202</code> 加 <code>4</code>，那是数字切分一课的事。</span></p><p>SentencePiece 的默认路径相反：不做语言特定正则，把空格映射成特殊标记 <code>▁</code>，整句在同一条序列上训练 BPE 或 Unigram。压缩率往往更高，因为「空格+词首」可以焊成一个符号；代价是词界变得只能靠 detokenize 还原，跨语言的公平性也更依赖训练语料的字符分布。</p>',14)),(o(),t(i,null,{default:a(()=>[r(n,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20TXT%5B%22%E5%90%8C%E4%B8%80%E6%AE%B5%E4%B8%AD%E8%8B%B1%E6%B7%B7%E6%8E%92%E6%96%87%E6%9C%AC%22%5D%20--%3E%20G%5B%22GPT-2%20%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20TXT%20--%3E%20S%5B%22SentencePiece%20%E8%B7%AF%E7%BA%BF%22%5D%0A%20%20G%20--%3E%20G1%5B%22%E6%AD%A3%E5%88%99%E6%8C%89%E7%B1%BB%E5%88%AB%E5%88%87%E5%9D%97%3A%20%E5%AD%97%E6%AF%8D%2F%E6%95%B0%E5%AD%97%2F%E6%A0%87%E7%82%B9%2F%E7%A9%BA%E7%99%BD%22%5D%0A%20%20G1%20--%3E%20G2%5B%22%E5%8F%AA%E5%9C%A8%E5%9D%97%E5%86%85%E5%90%88%E5%B9%B6%2C%20%E8%B7%A8%E7%95%8C%E6%B0%B8%E4%B8%8D%E7%84%8A%E6%8E%A5%22%5D%0A%20%20S%20--%3E%20S1%5B%22%E7%A9%BA%E6%A0%BC%E6%98%A0%E6%88%90%E4%B8%8B%E5%88%92%E7%BA%BF%E7%AC%A6%2C%20%E6%95%B4%E5%8F%A5%E4%B8%80%E6%9D%A1%E5%BA%8F%E5%88%97%22%5D%0A%20%20S1%20--%3E%20S2%5B%22%E5%85%A8%E5%BA%8F%E5%88%97%E5%90%88%E5%B9%B6%2C%20%E7%A9%BA%E6%A0%BC%E5%8F%AF%E7%84%8A%E8%BF%9B%E8%AF%8D%E9%A6%96%22%5D%0A%20%20G2%20--%3E%20O1%5B%22token%20%E6%95%B0%E5%81%8F%E5%A4%9A%2C%20%E8%AF%8D%E7%95%8C%E6%B8%85%E6%99%B0%22%5D%0A%20%20S2%20--%3E%20O2%5B%22token%20%E6%95%B0%E5%81%8F%E5%B0%91%2C%20%E8%AF%8D%E7%95%8C%E6%A8%A1%E7%B3%8A%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E('<h3 id="正则是词表的一部分" tabindex="-1">正则是词表的一部分 <a class="header-anchor" href="#正则是词表的一部分" aria-label="Permalink to &quot;正则是词表的一部分&quot;">​</a></h3><p>推理必须使用与训练完全相同的正则。改一条 <code>\\p{L}+</code> 为 <code>\\p{L}*</code>，同一段原文会变成另一条 token 序列，嵌入全部错位。部署时把正则、字节映射、合并表、特殊符号绑成一个快照，与模型版本一一对应。tiktoken 一类实现把这条正则编译进词表文件，而不是留在业务代码里随手改。</p><p><span class="marginnote">代码对正则极敏感。按「可选空格加字母」切，会把 <code>foo_bar</code> 拆开或整块留下，取决于 <code>_</code> 算不算字母。词表必须在含代码的混合物上训练，否则配置里的代码配比不等于模型看见的代码 token 数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预分词把合并的搜索空间从「任意相邻字节」收成「块内相邻字节」。块边界是硬约束：即使某跨块对在语料里出现百万次，合并表也看不见它。这保证 detokenize 时空白与标点仍按类别还原，也让英语词干大多落在同一块内，形态后缀有机会被单独焊住。</p><p>代价是压缩率的上限被正则锁死。数字若被 <code>\\p{N}+</code> 收成整块，后续 BPE 仍可能把 <code>2024</code> 焊成奇怪碎片——那是<a href="/llm/digit-splitting">数字切分</a>一课要补的缺口。字符类别定义依赖 Unicode 属性：全角数字、上标、罗马数字是否算 <code>\\p{N}</code>，会改变科学文本与 CJK 混排的切法。</p><p><span class="marginnote">常见误区：初学者容易以为全角「２０２４」和半角 <code>2024</code> 会被切成一样的 token。实际上全角字符的 UTF-8 字节完全不同，切出来的块也不同——中文文档里混入一个全角数字或全角标点，token 数就会悄悄暴涨，账单和上下文窗口都跟着变。</span></p>',7)),(o(),t(i,null,{default:a(()=>[r(n,{id:"mermaid-62",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E6%96%87%E6%9C%AC%22%5D%20--%3E%20RE%5B%22%E6%AD%A3%E5%88%99%E5%88%87%E6%88%90%E5%9D%97%22%5D%0A%20%20RE%20--%3E%20BY%5B%22%E5%9D%97%E5%86%85%E5%AD%97%E8%8A%82%E5%8C%96%22%5D%0A%20%20BY%20--%3E%20BPE%5B%22%E5%9D%97%E5%86%85%20BPE%20%2F%20Unigram%22%5D%0A%20%20BPE%20--%3E%20ID%5B%22token%20%E5%BA%8F%E5%88%97%22%5D%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[d(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=E('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>正则预分词不是句法分析。它不会识别 URL、邮箱或公式；复杂模式会把训练变慢，且几乎无法与 GPU 分词内核融合。过度定制的语言特定规则（例如单独列出所有英语缩写）会在其他语言上制造空洞。多语言词表更常见的做法是：一条相对粗的 Unicode 类别正则，加上字节回退兜底。</p><p>若任务需要跨空格的短语原子（命名实体、多词函数名），应在特殊 token 或后处理里解决，而不是把正则写成一部词典。预分词只负责「哪些边界永不合并」；「哪些片段值得占一个编号」仍由 <a href="/llm/bpe-merge-rule">BPE</a> 或 <a href="/llm/unigram-segmentation">Unigram</a> 在块内完成。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>本课不重讲合并表；只补合并之前的硬边界。</li><li>预分词正则按字符类别切块，禁止跨类焊对，是 GPT-2 一类字节 BPE 的前置承诺。</li><li>SentencePiece 可几乎不做预分词，空格参与合并，压缩更高、词界更糊。</li><li>正则与合并表必须同快照冻结；改正则等于换词表。</li><li>数字块、未见字节、特殊符号仍未处理，留给随后几课。</li><li>出处：Radford et al., <em>Language Models are Unsupervised Multitask Learners</em>, 2019；Kudo &amp; Richardson, <em>SentencePiece</em>, EMNLP 2018；Sennrich, Haddow, Birch, ACL 2016。</li></ul>',5))])}const f=l(B,[["render",A]]);export{u as __pageData,f as default};
